def transform(grid):
    from math import gcd
    from functools import reduce

    h, w = len(grid), len(grid[0])
    markers = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
               if grid[r][c] not in (0, 8)]
    eight = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8]
    if not markers or not eight:
        return [row[:] for row in grid]

    # The 8-shapes are made from equal square tiles.
    lengths = []
    for r in range(h):
        run = 0
        for c in range(w + 1):
            if c < w and grid[r][c] == 8:
                run += 1
            elif run:
                lengths.append(run)
                run = 0
    for c in range(w):
        run = 0
        for r in range(h + 1):
            if r < h and grid[r][c] == 8:
                run += 1
            elif run:
                lengths.append(run)
                run = 0
    k = reduce(gcd, lengths) if lengths else 1

    minr = min(r for r, c, color in markers)
    maxr = max(r for r, c, color in markers)
    minc = min(c for r, c, color in markers)
    maxc = max(c for r, c, color in markers)
    mh, mw = maxr - minr + 1, maxc - minc + 1

    # Rotate the marker pattern 90 degrees clockwise.
    rotated = {}
    for r, c, color in markers:
        rr, cc = r - minr, c - minc
        rotated[(cc, mh - 1 - rr)] = color

    expected = set(rotated)
    out = [row[:] for row in grid]

    # Find the tile alignment whose 8-tiles reproduce the rotated pattern.
    for phase_r in range(k):
        for phase_c in range(k):
            tiles = {}
            covered = set()
            for r in range(phase_r, h - k + 1, k):
                for c in range(phase_c, w - k + 1, k):
                    cells = {(rr, cc) for rr in range(r, r + k)
                             for cc in range(c, c + k)}
                    if all(grid[rr][cc] == 8 for rr, cc in cells):
                        q = ((r - phase_r) // k, (c - phase_c) // k)
                        tiles[q] = cells
                        covered.update(cells)

            if covered != set(eight) or len(tiles) != len(expected):
                continue

            actual = set(tiles)
            ar0 = min(r for r, c in actual)
            ac0 = min(c for r, c in actual)
            er0 = min(r for r, c in expected)
            ec0 = min(c for r, c in expected)
            actual_norm = {(r - ar0, c - ac0) for r, c in actual}
            expected_norm = {(r - er0, c - ec0) for r, c in expected}
            if actual_norm != expected_norm:
                continue

            for (er, ec), color in rotated.items():
                q = (ar0 + er - er0, ac0 + ec - ec0)
                for rr, cc in tiles[q]:
                    out[rr][cc] = color
            return out

    return out
